  vector: [0.15, 0.25, 0.35, 0.45],
  topK: 5,
  includeMetadata: true
});

// List all namespaces
const namespaces = await index.listNamespaces();
console.log(namespaces); // ["", "customer-123", "customer-456"]

// Delete namespace
await index.deleteNamespace("customer-123");
```

